  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["J5", "U3", "U2"],
      "pins": ["J5.2", "J5.4", "U3.1", "U3.5"],
      "nets": ["NET0006", "NET0008"],
      "observed": "On the AVR-ISP-6 header J5, pin 2 (MOSI) is wired to net NET0006, the same net as pin 4 (RST) and the ATtiny RESET/PB5 pin (U3.1 / U2.1).",
      "expected": "MOSI must connect to the ATtiny's MOSI/DI pin PB0, which is net NET0008 (U3.5 / U2.5); only RST should be on NET0006.",
      "evidence": [
        {"source": "schematic", "quote": "J5 AVR-ISP-6: MISO 1 NET0007, MOSI 2 NET0006, SCK 3 NET0002, RST 4 NET0006"},
        {"source": "schematic", "quote": "U3 ATtiny45-20P: PB0 5 NET0008, PB1 6 NET0007, PB2 7 NET0002, RESET/PB5 1 NET0006"}
      ],
      "impact": "MOSI is shorted to the RESET line, so ISP programming will fail (MOSI data toggles RESET) and in normal operation PB0/SDA is tied to the reset pin.",
      "confidence": 0.5
    },
    {
      "category": "wrong_value",
      "components": ["C1", "U1"],
      "pins": ["U1.2", "C1.1"],
      "nets": ["+5V"],
      "observed": "C1, the only capacitor on the LM1117-5.0 output rail (+5V), is 100 nF.",
      "expected": "The LM1117 requires a minimum output capacitance of about 10 uF for stability; 100 nF is far too small.",
      "evidence": [
        {"source": "schematic", "quote": "U1 LM1117-5.0: VO 2 -> +5V; C1 100nF from +5V to GND"}
      ],
      "impact": "The 5V rail may be unstable/oscillate, especially at light load.",
      "confidence": 0.3
    }
  ],
  "summary": "The AVR-ISP header J5 appears to have its MOSI pin tied to the RESET net NET0006 instead of PB0 (NET0008), shorting MOSI to RESET; the LM1117 output capacitor is also far below the recommended value."
}

